import React from 'react';
import { 
  Container, 
  Typography, 
  Grid, 
  Card, 
  CardContent, 
  Box,
  Button 
} from '@mui/material';
import LocalShippingIcon from '@mui/icons-material/LocalShipping';
import SupportAgentIcon from '@mui/icons-material/SupportAgent';
import SecurityIcon from '@mui/icons-material/Security';
import PaymentIcon from '@mui/icons-material/Payment';
import { useNavigate } from 'react-router-dom';

const WelcomePage = () => {
  const navigate = useNavigate();

  const services = [
    {
      icon: <LocalShippingIcon sx={{ fontSize: 50, color: 'primary.main' }} />,
      title: 'Free Shipping',
      description: 'Free shipping on all orders over $50'
    },
    {
      icon: <SupportAgentIcon sx={{ fontSize: 50, color: 'primary.main' }} />,
      title: '24/7 Support',
      description: 'Round the clock customer support'
    },
    {
      icon: <SecurityIcon sx={{ fontSize: 50, color: 'primary.main' }} />,
      title: 'Secure Payment',
      description: 'Safe and secure payment methods'
    },
    {
      icon: <PaymentIcon sx={{ fontSize: 50, color: 'primary.main' }} />,
      title: 'Easy Returns',
      description: '30-day money back guarantee'
    }
  ];

  return (
    <Box>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(45deg, #2C3E50 30%, #3498DB 90%)',
          color: 'white',
          py: 15,
          textAlign: 'center'
        }}
      >
        <Container maxWidth="md">
          <Typography variant="h2" component="h1" 
            sx={{ 
              fontWeight: 800,
              mb: 4,
              textShadow: '2px 2px 4px rgba(0,0,0,0.3)'
            }}>
            Welcome to Aura Store
          </Typography>
          <Typography variant="h5" sx={{ mb: 6 }}>
            Discover amazing products at incredible prices
          </Typography>
          <Button 
            variant="contained" 
            color="secondary" 
            size="large"
            onClick={() => navigate('/products')}
            sx={{ 
              py: 2, 
              px: 4,
              fontSize: '1.2rem'
            }}
          >
            Shop Now
          </Button>
        </Container>
      </Box>

      {/* Services Section */}
      <Container sx={{ py: 8 }}>
        <Typography variant="h3" component="h2" 
          sx={{ 
            textAlign: 'center', 
            mb: 8,
            fontWeight: 700
          }}>
          Our Services
        </Typography>
        <Grid container spacing={4}>
          {services.map((service, index) => (
            <Grid item xs={12} sm={6} md={3} key={index}>
              <Card 
                sx={{ 
                  height: '100%',
                  textAlign: 'center',
                  transition: 'transform 0.3s ease-in-out',
                  '&:hover': {
                    transform: 'translateY(-10px)'
                  }
                }}
              >
                <CardContent>
                  <Box sx={{ mb: 2 }}>
                    {service.icon}
                  </Box>
                  <Typography variant="h6" component="h3" sx={{ mb: 2 }}>
                    {service.title}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {service.description}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

export default WelcomePage;
